{
  "technical_and_design_decisions": [
    "Adopt Spring Boot 3.x (aligned with Spring Framework 6.0 and Java 17+ requirements) as the foundation for YARN application deployment functionality",
    "Use Apache Hadoop YARN ResourceManager REST APIs for all cluster interactions to minimize native YARN client dependency overhead and improve portability across YARN distributions",
    "Implement asynchronous deploy operations using a bounded, persistent task queue to decouple CLI user interactions from long-running YARN deployment tasks and prevent ResourceManager overload",
    "Extend Spring Boot's native JarLauncher class for module dependency resolution instead of building a custom classloader, to leverage well-tested Boot classloading logic and reduce maintenance burden",
    "Map deployment properties (YARN app name, queue, priority, resource reservations) to Spring's Environment abstraction to enable consistent runtime configuration override via CLI, manifest, or external config files",
    "Use the Maven Resolver API for resolving module external JAR dependencies to align with standard Java ecosystem build and dependency management practices"
  ],
  "assumptions": [
    "An existing Spring Cloud Data Flow (s-c-d) and Spring Cloud Stream (s-c-s) base codebase is available for extension, eliminating the need to build core application infrastructure from scratch",
    "Target YARN clusters run Hadoop 3.3 or later, which supports all required ResourceManager REST APIs for application deployment and instance management",
    "All module external dependencies are published to a Maven-compatible repository that is accessible from both the deployment environment and YARN cluster nodes",
    "The existing ModuleLauncher interface has a stable, minimal public API that can be adapted to extend JarLauncher without breaking existing custom module implementations",
    "A local MiniYARN test environment is available for integration testing, eliminating the need for access to a production YARN cluster during development",
    "Security policies allow the deployment service to access HDFS and YARN ResourceManager APIs with the required permissions for asset upload and application submission"
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "HDFS Manifest Parsing and Asset Upload Implementation",
      "activity_description": "Develop functionality to parse deployment manifests, validate required fields (appType, appName, asset paths), and automatically upload all required application assets (JARs, configuration files) to the specified HDFS directory prior to YARN application submission.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "YARN ResourceManager REST API Integration for Group Deployment",
      "activity_description": "Implement integration with YARN ResourceManager REST endpoints to submit YARN applications for groups of modules, handle app-specific parameters (e.g., appType=CLOUDDATA, appName=spring-cloud-data-yarn-app), and manage application instance lifecycle operations (start, stop, status checks).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A3",
      "activity_name": "Configurable YARN App Instance Properties Support",
      "activity_description": "Add support for deployment properties to define per-module YARN application configurations (custom app name, queue assignment, priority, memory/CPU resource reservations), integrate with Spring's property resolution to allow runtime override via CLI properties as specified in user story U3.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A4",
      "activity_name": "Asynchronous Deploy Operation Queue Implementation",
      "activity_description": "Refactor the existing deployer to run operations asynchronously using a bounded task queue, return immediate responses to shell CLI commands, and queue YARN deployment tasks to avoid blocking user interactions and prevent overwhelming the YARN ResourceManager.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A5",
      "activity_name": "Module External JAR Resolution for Boot Loader",
      "activity_description": "Develop logic to resolve external JAR dependencies required by out-of-the-box (OOTB) modules, integrate with Maven Resolver to fetch dependencies from configured repositories, and add resolved JARs to the Spring Boot loader classpath at runtime.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A6",
      "activity_name": "ModuleLauncher Contract Refactor to Extend JarLauncher",
      "activity_description": "Refactor the existing ModuleLauncher interface to extend Spring Boot's native JarLauncher API, remove duplicate functionality between the custom implementation and Boot's built-in logic, and ensure backward compatibility for existing custom module implementations.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A7",
      "activity_name": "JAR Resolution Documentation and Test Case Development",
      "activity_description": "Create comprehensive documentation for the JAR resolution and Boot loader integration approach, including usage examples for porting modules with external dependencies, and implement unit and integration test cases covering dependency resolution, classpath loading, and edge cases (missing dependencies, version conflicts).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A8",
      "activity_name": "Uniform External Library Support for Modules",
      "activity_description": "Implement end-to-end support for consuming external libraries across all module types, integrate the JAR resolution logic from A5 with the deployer and module launcher components, and add validation for allowed external dependencies to mitigate security risks.",
      "most_likely_effort": 14
    }
  ],
  "reported_total": {
    "most_likely_effort": 130
  }
}

